package com.collegewise.dto;
import jakarta.validation.constraints.*;import org.springframework.data.domain.Page;import com.collegewise.entity.*;import java.time.Instant;
public final class ApiDtos { private ApiDtos(){} public record Register(@NotBlank @Size(max=120) String name,@NotBlank @Email @Size(max=190) String email,@NotBlank @Size(min=12,max=72) String password){} public record Login(@NotBlank @Email @Size(max=190) String email,@NotBlank String password){} public record Token(String token,String tokenType,String role,String name){} public record ProfileUpdate(@Size(max=20) String phone,@DecimalMin("0") @DecimalMax("100") Double tenthPercentage,@DecimalMin("0") @DecimalMax("100") Double twelfthPercentage,@Size(max=50) String entranceExam,@Min(2000) @Max(2100) Integer examYear,@Positive Integer rank,@DecimalMin("0") @DecimalMax("100") Double percentile,@Size(max=40) String category,@Size(max=80) String preferredCourse,@Size(max=80) String preferredBranch,@Size(max=80) String preferredState,@Size(max=80) String preferredCity,@PositiveOrZero Double maximumBudget,Boolean hostelRequired,@Size(max=120) String careerInterest){} public record CollegeRequest(@NotBlank @Size(max=160) String name,@Size(max=2000) String description,@NotBlank @Size(max=80) String state,@NotBlank @Size(max=80) String city,@Size(max=240) String address,@Size(max=300) String website,@Size(max=40) String collegeType,@Min(1800) Integer establishedYear,@PositiveOrZero Double fees,@Positive Integer ranking,Boolean hostelAvailable,@Size(max=80) String accreditation,@Size(max=500) String imageUrl){} public record CollegeResponse(Long id,String name,String description,String state,String city,String address,String website,String collegeType,Integer establishedYear,Double fees,Integer ranking,boolean hostelAvailable,String accreditation,String imageUrl){public static CollegeResponse from(College c){return new CollegeResponse(c.getId(),c.getName(),c.getDescription(),c.getState(),c.getCity(),c.getAddress(),c.getWebsite(),c.getCollegeType(),c.getEstablishedYear(),c.getFees(),c.getRanking(),c.isHostelAvailable(),c.getAccreditation(),c.getImageUrl());}} public record CollegeDetailsResponse(CollegeResponse college,java.util.List<CourseResponse> courses,java.util.List<BranchResponse> branches,java.util.List<CutoffResponse> cutoffs,java.util.List<PlacementResponse> placements){} public record ProfileResponse(String name,String email,String phone,Double tenthPercentage,Double twelfthPercentage,String entranceExam,Integer examYear,Integer rank,Double percentile,String category,String preferredCourse,String preferredBranch,String preferredState,String preferredCity,Double maximumBudget,Boolean hostelRequired,String careerInterest){public static ProfileResponse from(StudentProfile p){return new ProfileResponse(p.getUser().getName(),p.getUser().getEmail(),p.getPhone(),p.getTenthPercentage(),p.getTwelfthPercentage(),p.getEntranceExam(),p.getExamYear(),p.getRank(),p.getPercentile(),p.getCategory(),p.getPreferredCourse(),p.getPreferredBranch(),p.getPreferredState(),p.getPreferredCity(),p.getMaximumBudget(),p.getHostelRequired(),p.getCareerInterest());}} public record UserResponse(Long id,String name,String email,String role,boolean active,Instant createdAt){public static UserResponse from(User u){return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole().name(),u.isActive(),u.getCreatedAt());}} public record CourseResponse(Long id,String name,String description){public static CourseResponse from(Course c){return new CourseResponse(c.getId(),c.getName(),c.getDescription());}} public record BranchResponse(Long id,Long collegeId,String name,String description){public static BranchResponse from(Branch b){return new BranchResponse(b.getId(),b.getCollege().getId(),b.getName(),b.getDescription());}} public record CutoffResponse(Long id,Long collegeId,Long courseId,Long branchId,String entranceExam,Integer examYear,String category,Integer closingRank,Double closingPercentile){public static CutoffResponse from(Cutoff c){return new CutoffResponse(c.getId(),c.getCollege().getId(),c.getCourse()==null?null:c.getCourse().getId(),c.getBranch()==null?null:c.getBranch().getId(),c.getEntranceExam(),c.getExamYear(),c.getCategory(),c.getClosingRank(),c.getClosingPercentile());}} public record PlacementResponse(Long id,Long collegeId,Long courseId,Integer year,Integer studentsPlaced,Integer studentsEligible,Double averagePackage,Double highestPackage){public static PlacementResponse from(Placement p){return new PlacementResponse(p.getId(),p.getCollege().getId(),p.getCourse()==null?null:p.getCourse().getId(),p.getYear(),p.getStudentsPlaced(),p.getStudentsEligible(),p.getAveragePackage(),p.getHighestPackage());}} public record Recommendation(Long collegeId,String collegeName,int score,String admissionCompatibility,String explanation,java.util.List<String> reasons,java.util.List<String> concerns){} public record HistoryResponse(Long id,Long collegeId,String collegeName,int score,Instant createdAt){public static HistoryResponse from(RecommendationHistory h){return new HistoryResponse(h.getId(),h.getCollege().getId(),h.getCollege().getName(),h.getScore(),h.getCreatedAt());}} public record PageResponse<T>(java.util.List<T> content,int number,int size,long totalElements,int totalPages,boolean first,boolean last){public static <T> PageResponse<T> from(Page<T> page){return new PageResponse<>(page.getContent(),page.getNumber(),page.getSize(),page.getTotalElements(),page.getTotalPages(),page.isFirst(),page.isLast());}} }
